using System.Text.Json;
using AmllTtmlTool.Core.Models;

namespace AmllTtmlTool.Core.Tests;

// Parity against the ORIGINAL Rust/WASM engine run offline (node, repo
// node_modules only). Goldens generated by Tools/generate-ttml-goldens.mjs:
//   <name>.wasm.json = ttmlToAmll + TS-wrapper transforms of <name>.xml
//   <name>.wasm.xml  = amllToTtml of the postprocessed JSON (+xml:lang
//                     backfill, i.e. the true app path)
// C# side mirrors the app path: Parse -> ApplyImportRenames -> backfill
// language from xml:lang -> Generate. 14/14 existing fixtures were verified
// byte-identical through this path during development (see PROGRESS.md).
public sealed class WasmParityTests
{
    private static readonly string Fixtures =
        Path.Combine(AppContext.BaseDirectory, "Fixtures");

    public static IEnumerable<object[]> FixtureFlags() => new[]
    {
        new object[] { "gen-simple", false, false, false },
        new object[] { "gen-rich", false, false, false },
        new object[] { "gen-rich-pretty", false, true, false },
        new object[] { "gen-duet-roman", false, false, false },
        new object[] { "gen-empty-bgfirst", false, false, false },
        new object[] { "gen-linetiming", false, false, true },
        new object[] { "gen-apple-rules", true, false, false },
        new object[] { "gen-itunes-meta", false, false, false },
        new object[] { "gen-only-empty", false, false, false },
        new object[] { "gen-main-then-empty", false, false, false },
        new object[] { "gen-empty-then-main", false, false, false },
        new object[] { "gen-blank-words", false, false, false },
        new object[] { "gen-lead-bg", false, false, false },
        new object[] { "gen-lead-duetbg", false, false, false },
    };

    public static IEnumerable<object[]> FixtureNames() =>
        FixtureFlags().Select(f => new object[] { (string)f[0] });

    internal static TtmlLyric AppPathRecords(string xml)
    {
        var parsed = TtmlParser.Parse(xml);
        Assert.True(parsed.Success);
        // Full app import path (useFileOpener): wrapper renames, legacy
        // repair, then xml:lang backfill.
        var repaired = LegacyTtml.RepairLegacyImport(parsed.Data!, xml).Result;
        var norm = TtmlNormalize.ApplyImportRenames(repaired);
        // WRAPPER-4 importer backfill (useFileOpener): xml:lang appended
        // LAST when no language metadata survived the strip.
        var lang = LegacyTtml.ExtractXmlLang(xml);
        if (lang is not null && !norm.Metadata.Any(m =>
                m.Key.Equals("language", StringComparison.OrdinalIgnoreCase)))
        {
            norm = norm with
            {
                Metadata = [.. norm.Metadata, new TtmlMetadata("language", [lang])],
            };
        }
        return norm;
    }

    [Theory]
    [MemberData(nameof(FixtureNames))]
    public void Parse_Matches_Wasm_Json(string fixture)
    {
        var xml = File.ReadAllText(Path.Combine(Fixtures, fixture + ".xml"));
        var records = AppPathRecords(xml);
        using var wasm = JsonDocument.Parse(
            File.ReadAllText(Path.Combine(Fixtures, fixture + ".wasm.json")));
        var root = wasm.RootElement;
        // The backfilled language meta is importer behavior, not parser
        // output — exclude it from the parse comparison.
        var comparable = records.Metadata
            .Where(m => !m.Key.Equals("language", StringComparison.OrdinalIgnoreCase))
            .ToList();
        var wmeta = root.GetProperty("metadata").EnumerateArray().ToList();
        Assert.Equal(wmeta.Count, comparable.Count);
        for (var i = 0; i < wmeta.Count; i++)
        {
            Assert.Equal(wmeta[i].GetProperty("key").GetString(), comparable[i].Key);
            Assert.Equal(
                wmeta[i].GetProperty("value").EnumerateArray().Select(v => v.GetString() ?? string.Empty).ToList(),
                comparable[i].Value);
        }
        var wlines = root.GetProperty("lyricLines").EnumerateArray().ToList();
        Assert.Equal(wlines.Count, records.LyricLines.Count);
        for (var i = 0; i < wlines.Count; i++)
            AssertLine(wlines[i], records.LyricLines[i]);
    }

    internal static void AssertLine(JsonElement wl, LyricLine line)
    {
        Assert.Equal(wl.GetProperty("startTime").GetDouble(), line.StartTime);
        Assert.Equal(wl.GetProperty("endTime").GetDouble(), line.EndTime);
        Assert.Equal(wl.GetProperty("isBG").GetBoolean(), line.IsBg);
        Assert.Equal(wl.GetProperty("isDuet").GetBoolean(), line.IsDuet);
        Assert.Equal(wl.GetProperty("translatedLyric").GetString(), line.TranslatedLyric);
        Assert.Equal(wl.GetProperty("romanLyric").GetString(), line.RomanLyric);
        var ww = wl.GetProperty("words").EnumerateArray().ToList();
        Assert.Equal(ww.Count, line.Words.Count);
        for (var i = 0; i < ww.Count; i++)
        {
            Assert.Equal(ww[i].GetProperty("startTime").GetDouble(), line.Words[i].StartTime);
            Assert.Equal(ww[i].GetProperty("endTime").GetDouble(), line.Words[i].EndTime);
            Assert.Equal(ww[i].GetProperty("word").GetString(), line.Words[i].Word);
            var roman = ww[i].TryGetProperty("romanWord", out var rw) ? rw.GetString() ?? "" : "";
            Assert.Equal(roman, line.Words[i].RomanWord);
            var obscene = ww[i].TryGetProperty("obscene", out var ob) && ob.GetBoolean();
            Assert.Equal(obscene, line.Words[i].Obscene);
            var beats = ww[i].TryGetProperty("emptyBeat", out var eb) ? eb.GetDouble() : 0;
            Assert.Equal(beats, line.Words[i].EmptyBeat);
            var wruby = ww[i].TryGetProperty("ruby", out var rb)
                ? rb.EnumerateArray().ToList() : new List<JsonElement>();
            var ruby = line.Words[i].Ruby ?? new List<LyricWordBase>();
            Assert.Equal(wruby.Count, ruby.Count);
            for (var r = 0; r < wruby.Count; r++)
            {
                Assert.Equal(wruby[r].GetProperty("startTime").GetDouble(), ruby[r].StartTime);
                Assert.Equal(wruby[r].GetProperty("endTime").GetDouble(), ruby[r].EndTime);
                var text = wruby[r].TryGetProperty("text", out var tx)
                    ? tx.GetString() : wruby[r].GetProperty("word").GetString();
                Assert.Equal(text, ruby[r].Word);
            }
        }
    }

    [Theory]
    [MemberData(nameof(FixtureFlags))]
    public void Generate_Matches_Wasm_ByteForByte(
        string fixture, bool apple, bool pretty, bool lineTiming)
    {
        var xml = File.ReadAllText(Path.Combine(Fixtures, fixture + ".xml"));
        var records = AppPathRecords(xml);
        var gen = TtmlGenerator.Generate(records, new(), new(apple, pretty, lineTiming));
        Assert.True(gen.Success);
        Assert.Equal(
            File.ReadAllText(Path.Combine(Fixtures, fixture + ".wasm.xml")),
            gen.Data);
    }
}
